import {randomUUID,createHash} from 'node:crypto';
import type pg from 'pg';
import {Prisma,type PrismaClient,requireWebBaby,withWebTransaction,WebAccessError} from '@growdesk/database';
import {canonicalJsonStringify,type CreateAiRunRequest,type AiRunConfirmRequest} from '@growdesk/contracts';
import type {UserPrincipal} from '@growdesk/domain';
import {assertAiProviderConfigured} from './ai-provider-preflight.js';
import {executeCareAction,joinDomainTransaction,validateCareAction,type CareAction} from './ai-action-executor.js';
interface Session {id:string;user_id:string;baby_id:string|null}
interface Row {id:string;session_id:string;user_id:string;baby_id:string|null;status:string;attempt:number;last_event_seq:string;result_summary:string|null;proposed_plan:unknown;error_code:string|null;error_message:string|null;error_details:{code?:string;message?:string}|null;created_at:Date;started_at:Date|null;finished_at:Date|null;result_ref:Record<string,unknown>|null}
const dto=(r:Row)=>({id:r.id,sessionId:r.session_id,userId:r.user_id,babyId:r.baby_id,status:r.status,attempt:Math.max(1,r.attempt),lastEventSeq:String(r.last_event_seq),resultSummary:r.result_summary,proposedPlan:r.proposed_plan,errorCode:r.error_code??r.error_details?.code??null,errorMessage:r.error_message??r.error_details?.message??null,createdAt:r.created_at.toISOString(),startedAt:r.started_at?.toISOString()??null,finishedAt:r.finished_at?.toISOString()??null});
const sqlRow="SELECT r.*,t.status,t.attempt,t.error_details,t.result_ref FROM ai_runs r JOIN task_executions t ON t.id=r.id";
export class DurableChatService {
  constructor(private readonly prisma:PrismaClient,private readonly pool:pg.Pool){}
  private async session(db:Pick<pg.Pool,'query'>,user:string,id:string,lock=false):Promise<Session>{
    const r=(await db.query<Session>(`SELECT id,user_id,baby_id FROM ai_sessions WHERE id=$1 AND user_id=$2${lock?' FOR UPDATE':''}`,[id,user])).rows[0];
    if(!r)throw new WebAccessError(404,'SESSION_NOT_FOUND','Conversation is not accessible');if(r.baby_id)await requireWebBaby(db,user,r.baby_id,lock);return r;
  }
  private async run(db:Pick<pg.Pool,'query'>,user:string,id:string,lock=false):Promise<Row>{
    const r=(await db.query<Row>(`${sqlRow} WHERE r.id=$1 AND r.user_id=$2${lock?' FOR UPDATE OF t,r':''}`,[id,user])).rows[0];
    if(!r)throw new WebAccessError(404,'RUN_NOT_FOUND','Run is not accessible');await this.session(db,user,r.session_id);return r;
  }
  async create(principal:UserPrincipal,sessionId:string,body:CreateAiRunRequest){
    const digest=createHash('sha256').update(`${sessionId}:${body.clientMessageId}`).digest('hex');const id=`${digest.slice(0,8)}-${digest.slice(8,12)}-5${digest.slice(13,16)}-a${digest.slice(17,20)}-${digest.slice(20,32)}`;
    return withWebTransaction(this.pool,async db=>{
      const s=await this.session(db,principal.userId,sessionId,true);const requestHash=createHash('sha256').update(canonicalJsonStringify(body)).digest('hex');
      const prior=(await db.query<{payload:{requestHash?:string}}>('SELECT payload FROM task_outbox WHERE aggregate_id=$1 ORDER BY created_at LIMIT 1',[id])).rows[0];
      if(prior){if(prior.payload.requestHash!==requestHash)throw new WebAccessError(409,'MESSAGE_ID_REUSED','This message ID already has different input');return {data:dto(await this.run(db,principal.userId,id))};}
      const active=await db.query("SELECT r.id FROM ai_runs r JOIN task_executions t ON t.id=r.id WHERE r.session_id=$1 AND t.status IN ('queued','running','cancelling','awaiting_confirmation')",[sessionId]);
      if(active.rowCount)throw new WebAccessError(409,'SESSION_RUN_ACTIVE','Finish or cancel the current run first');assertAiProviderConfigured();
      for(const attachmentId of body.attachmentIds??[]){const a=await db.query("SELECT id FROM attachments WHERE id=$1 AND uploader_id=$2 AND baby_id=$3 AND status='ready' AND deleted_at IS NULL AND mime_type IN ('image/jpeg','image/png','image/webp') FOR SHARE",[attachmentId,principal.userId,s.baby_id]);if(!a.rowCount)throw new WebAccessError(404,'ATTACHMENT_NOT_FOUND','Private image is not available');}
      const oldMessage=await db.query<{session_id:string;content:string;role:string}>('SELECT session_id,content,role FROM ai_messages WHERE id=$1',[body.clientMessageId]);if(oldMessage.rowCount)throw new WebAccessError(409,'MESSAGE_ID_REUSED','Message already exists outside this run');
      await db.query(`INSERT INTO ai_messages(id,session_id,role,content,image,created_at) VALUES($1,$2,'user',$3,$4,clock_timestamp())`,[body.clientMessageId,sessionId,body.message,body.attachmentIds?.length?JSON.stringify(body.attachmentIds.map(a=>`/api/attachments/${a}`)):null]);
      await db.query(`INSERT INTO task_executions(id,kind,owner_scope,status,attempt,max_attempts,created_at,updated_at) VALUES($1,'ai_chat_run',$2,'queued',0,1,clock_timestamp(),clock_timestamp())`,[id,`user:${principal.userId}`]);
      await db.query(`INSERT INTO ai_runs(id,session_id,user_id,baby_id,last_event_seq,created_at,updated_at) VALUES($1,$2,$3,$4,1,clock_timestamp(),clock_timestamp())`,[id,sessionId,principal.userId,s.baby_id]);
      await db.query(`INSERT INTO task_outbox(id,type,aggregate_id,payload_version,payload,phase_key,dispatch_state) VALUES($1,'ai_chat_run',$2,1,$3::jsonb,'initial','active')`,[randomUUID(),id,JSON.stringify({...body,sessionId,requestHash})]);
      await db.query(`INSERT INTO ai_run_events(id,run_id,sequence,event_type,payload) VALUES($1,$2,1,'queued',$3::jsonb)`,[randomUUID(),id,JSON.stringify({clientMessageId:body.clientMessageId,attempt:1})]);
      await db.query('UPDATE ai_sessions SET updated_at=clock_timestamp() WHERE id=$1',[sessionId]);return {data:dto(await this.run(db,principal.userId,id))};
    });
  }
  async get(user:string,id:string){return {data:dto(await this.run(this.pool,user,id))};}
  async latest(user:string,sessionId:string){await this.session(this.pool,user,sessionId);const r=(await this.pool.query<Row>(`${sqlRow} WHERE r.session_id=$1 AND r.user_id=$2 ORDER BY r.created_at DESC,r.id DESC LIMIT 1`,[sessionId,user])).rows[0];return {data:r?dto(r):null};}
  async events(user:string,id:string,after=0n,limit=100){const r=await this.run(this.pool,user,id);const events=await this.pool.query<{sequence:string;event_type:string;payload:Record<string,unknown>}>('SELECT sequence,event_type,payload FROM ai_run_events WHERE run_id=$1 AND sequence>$2 ORDER BY sequence LIMIT $3',[id,after.toString(),Math.min(Math.max(limit,1),100)]);return {status:r.status,terminal:['succeeded','failed','cancelled','awaiting_confirmation'].includes(r.status),events:events.rows.map(e=>{const {attempt,...payload}=e.payload;return {runId:id,seq:String(e.sequence),attempt:typeof attempt==='number'?attempt:Math.max(r.attempt,1),type:e.event_type,payload};})};}
  async cancel(user:string,id:string){return withWebTransaction(this.pool,async db=>{const r=await this.run(db,user,id,true);if(!['succeeded','failed','cancelled'].includes(r.status)){await db.query("UPDATE task_executions SET status='cancelled',cancel_requested_at=clock_timestamp(),fence_token=fence_token+1,lease_owner=NULL,lease_expires_at=NULL,updated_at=clock_timestamp() WHERE id=$1",[id]);await db.query('UPDATE ai_runs SET finished_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=$1',[id]);await db.query("UPDATE task_outbox SET dispatch_state='closed' WHERE aggregate_id=$1",[id]);}return {data:{success:true}};});}
  async retry(user:string,id:string,commandId:string){return withWebTransaction(this.pool,async db=>{const r=await this.run(db,user,id,true);const receipt=await db.query('SELECT command_id FROM web_chat_retries WHERE run_id=$1 AND command_id=$2',[id,commandId]);if(receipt.rowCount)return {data:{runId:id,newAttempt:r.attempt+1,status:'queued' as const}};if(!['failed','cancelled'].includes(r.status))throw new WebAccessError(409,'RUN_NOT_RETRYABLE','Only failed or cancelled runs can be explicitly retried');assertAiProviderConfigured();await db.query('INSERT INTO web_chat_retries(run_id,command_id) VALUES($1,$2)',[id,commandId]);await db.query("UPDATE task_executions SET status='queued',max_attempts=attempt+1,cancel_requested_at=NULL,fence_token=fence_token+1,lease_owner=NULL,lease_expires_at=NULL,result_ref=NULL,error_details=NULL,updated_at=clock_timestamp() WHERE id=$1",[id]);await db.query('UPDATE ai_runs SET proposed_plan=NULL,result_summary=NULL,error_code=NULL,error_message=NULL,started_at=NULL,finished_at=NULL,updated_at=clock_timestamp() WHERE id=$1',[id]);await db.query(`INSERT INTO task_outbox(id,type,aggregate_id,payload_version,payload,phase_key,dispatch_state) VALUES($1,'ai_chat_run',$2,1,'{}'::jsonb,$3,'active')`,[randomUUID(),id,`retry:${commandId}`]);return {data:{runId:id,newAttempt:r.attempt+1,status:'queued' as const}};});}
  async confirm(principal:UserPrincipal,id:string,body:AiRunConfirmRequest){
    return this.prisma.$transaction(async tx=>{
      const rows=await tx.$queryRaw<Row[]>(Prisma.sql`SELECT r.*,t.status,t.result_ref FROM ai_runs r JOIN task_executions t ON t.id=r.id WHERE r.id=${id} AND r.user_id=${principal.userId} FOR UPDATE OF t,r`);const r=rows[0];if(!r)throw new WebAccessError(404,'RUN_NOT_FOUND','Run is not accessible');
      // Session ownership and current memberships are checked again by each domain transaction.
      const current=await tx.aiSession.findUnique({where:{id:r.session_id}});if(!current||current.userId!==principal.userId||!r.baby_id)throw new WebAccessError(404,'SESSION_NOT_FOUND','Baby-scoped conversation is required');
      const membership=await tx.$queryRaw<Array<{role:string;family_role:string}>>(Prisma.sql`
        SELECT bm.role,fm.role AS family_role FROM babies b JOIN families f ON f.id=b.family_id
        JOIN baby_members bm ON bm.baby_id=b.id AND bm.family_id=b.family_id AND bm.user_id=${principal.userId}
        JOIN family_members fm ON fm.family_id=b.family_id AND fm.user_id=bm.user_id
        WHERE b.id=${r.baby_id} AND b.deleted_at IS NULL AND f.deleted_at IS NULL
        AND bm.status='active' AND bm.deleted_at IS NULL AND fm.status='active' AND fm.deleted_at IS NULL
        FOR SHARE OF b,f,bm,fm`);
      if(!membership[0])throw new WebAccessError(404,'BABY_NOT_FOUND','Baby access was revoked');
      if(membership[0].role==='viewer'||membership[0].family_role==='viewer')throw new WebAccessError(403,'BABY_WRITE_DENIED','Read-only member cannot confirm changes');
      const plan=r.proposed_plan as {actions:CareAction[];planHash:string;expiresAt:string}|null;
      if(r.status==='succeeded'&&r.result_ref?.planHash===body.planHash&&JSON.stringify(r.result_ref.actionIds)===JSON.stringify(body.actionIds))return {data:{runId:id,status:'succeeded' as const,appliedActionCount:body.actionIds.length}};
      if(r.status!=='awaiting_confirmation'||!plan||plan.planHash!==body.planHash||Date.parse(plan.expiresAt)<=Date.now()||!Number.isFinite(Date.parse(plan.expiresAt)))throw new WebAccessError(409,'PLAN_CONFLICT','Plan changed, expired or run is no longer awaiting confirmation');
      const hash=createHash('sha256').update(canonicalJsonStringify(plan.actions)).digest('hex');const legacyHash=createHash('sha256').update(JSON.stringify(plan.actions)).digest('hex');if(hash!==plan.planHash&&legacyHash!==plan.planHash)throw new WebAccessError(409,'PLAN_CONFLICT','Stored plan hash does not match');
      const wanted=new Set(body.actionIds);const selected=plan.actions.filter(a=>wanted.has(a.actionId));if(!wanted.size||wanted.size!==body.actionIds.length||selected.length!==wanted.size||selected.length>20)throw new WebAccessError(400,'AI_ACTION_INVALID','Choose unique actions from the persisted plan');selected.forEach(validateCareAction);
      const joined=joinDomainTransaction(tx);const results:unknown[]=[];for(const action of selected)results.push(await executeCareAction(joined,principal,r.baby_id,action));
      await tx.taskExecution.update({where:{id},data:{status:'succeeded',resultRef:{planHash:body.planHash,actionIds:body.actionIds,results:JSON.parse(JSON.stringify(results))},updatedAt:new Date()}});
      await tx.aiRun.update({where:{id},data:{resultSummary:`已确认并保存 ${selected.length} 项记录`,proposedPlan:Prisma.DbNull,finishedAt:new Date(),updatedAt:new Date()}});
      await tx.$executeRaw(Prisma.sql`UPDATE ai_messages SET tools_json=${JSON.stringify(selected.map(a=>({name:a.entityType,status:'done',summary:a.summary})))}
        WHERE id=${id} AND session_id=${r.session_id} AND role='assistant'`);
      await tx.aiSession.update({where:{id:r.session_id},data:{updatedAt:new Date()}});
      return {data:{runId:id,status:'succeeded' as const,appliedActionCount:selected.length}};
    },{timeout:60000});
  }
}
